{% from "hipersign_trading/templates/print/macros.html" import styles, header, items, totals, signs, bank %}
{{ styles() }}
<div class="hs-doc">
{{ header("PROFORMA INVOICE", "فاتورة مبدئية", doc.name|replace("SO-","PI-"), doc.transaction_date, doc.company) }}
<div class="hs-two"><div><div class="hs-h4">Buyer · المشتري</div><b>{{ doc.customer_name }}</b><br>{{ doc.address_display or "" }}{% if doc.contact_display %}<br>Attn: {{ doc.contact_display }}{% if doc.contact_mobile %} · {{ doc.contact_mobile }}{% endif %}{% endif %}{% if doc.tax_id %}<br>TRN {{ doc.tax_id }}{% endif %}</div><div><div class="hs-h4">Terms · الشروط</div>Incoterm: {{ doc.incoterm or "—" }} {{ doc.named_place or "" }}<br>Payment: {{ doc.hs_payment_method or doc.payment_terms_template or "As agreed" }}<br>Shipment: {{ doc.hs_shipment_mode or "—" }} · Your PO {{ doc.po_no or "—" }}<br>Validity: 15 days</div></div>
{{ items(doc, show_hs=True) }}
{{ totals(doc) }}
{% if doc.hs_is_export %}<div class="hs-note"><b>Export of goods — zero-rated for UAE VAT (0%).</b></div>{% endif %}
{{ bank(doc) }}
{{ signs("For " ~ doc.company, "Accepted by the buyer") }}
</div>
